let state;const locales=['ru','en','be','pl'];const t=k=>(words[k]||[k,k,k,k])[locales.indexOf(state.locale)];const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;const btn=(action,label,cls='',id='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${extra} ${state?.busy&&['start','finish','confirm','select-helper','apply','withdraw'].includes(action)?'disabled':''}>${state?.busy&&state?.pendingId===id&&['start','finish','confirm','select-helper','apply','withdraw'].includes(action)?t('pending'):label}</button>`;
const date=(v,withTime=true,zone='Europe/Minsk')=>new Intl.DateTimeFormat(state.locale,{day:'numeric',month:'short',...(withTime?{hour:'2-digit',minute:'2-digit'}:{year:'numeric'}),timeZone:zone}).format(new Date(v));
const role=r=>t(r==='owner'?'youOwner':'youHelper');const reviewNoun=n=>{const p=new Intl.PluralRules(state.locale).select(n);return state.locale==='en'?`${n} ${p==='one'?'review':'reviews'}`:state.locale==='pl'?`${n} ${p==='one'?'opinia':p==='few'?'opinie':'opinii'}`:`${n} ${p==='one'?'отзыв':p==='few'?'отзыва':'отзывов'}`.replace(/отзыв/g,state.locale==='be'?'водгук':'отзыв')};
const completedNoun=n=>state.locale==='en'?`${n} completed walks`:state.locale==='pl'?`${n} zakończonych spacerów`:state.locale==='be'?`${n} завершаных прагулак`:`${n} завершённых прогулок`;
const photo=(kind='owner',missing=false,small=false)=>missing?`<span class="avatar ${kind==='pet'?'pet':''} ${small?'small':''}" aria-label="${esc(kind==='pet'?t('petName'):'Александра')}">${icon(kind==='pet'?'paw-print':'user-round')}</span>`:`<img class="avatar ${kind==='pet'?'pet':''} ${small?'small':''}" src="walking-assets/${kind}.jpg" alt="">`;
