function reset(){state={accountId:'synthetic-account-001',mode:'owner',tab:'current',view:'hub',param:null,locale:$('#locale').value,scenario:$('#scenario').value,theme:$('#theme').value,scale:$('#scale').value,width:$('#width').value,profileRole:'owner',walks:fixtures(),history:Array.from({length:30},(_,i)=>({id:`past-${i}`,pet:['Луна','Арчи','Буся','Фея'][i%4],person:['Ульяна','Ирина','Анна','Максим'][i%4],role:i%2?'helper':'owner',status:i%5===4?'cancelled':'completed',date:new Date(Date.UTC(2026,9,10-i,14)).toISOString(),chat:i%5!==4,reviewed:i>2&&i%3===0})),historyLimit:6,historyLoading:false,historyError:false,period:'all',scroll:{},stack:[],sheet:null,busy:false,failNext:false,drafts:{},expanded:{},replies:{},messages:{},actionErrors:{},preferences:{city:'Минск · Центральный район',bio:'Гуляю спокойно. Учитываю привычки питомца, опыт с собаками — 4 года.',sizes:'small',areas:'Центральный, Советский',weekdays:true,weekends:true,zone:'Europe/Minsk',schedule:Array.from({length:7},(_,i)=>({day:i+1,enabled:true,start:i<5?'18:00':'09:00',end:i<5?'21:00':'18:00'}))},feedback:''};history.replaceState({depth:0},'',location.pathname);render()}
function remember(){const p=$('.page');if(p)state.scroll[`${state.mode}:${state.view}:${state.tab}`]=p.scrollTop}
function navigate(view,param=null){if(state.sheet)return;remember();state.stack.push({view:state.view,param:state.param,tab:state.tab});state.view=view;state.param=param;history.pushState({depth:state.stack.length},'',`#${view}${param?'/'+param:''}`);render()}
function back(){history.back()}
window.addEventListener('popstate',e=>{if(state.busy&&state.sheet){if(!e.state?.sheet)history.forward();return}if(state.sheet&&e.state?.sheet)return;const closing=state.sheet;if(state.sheet){$('#sheet').close();state.sheet=null}const depth=e.state?.depth??0;while(state.stack.length>depth){const prev=state.stack.pop();Object.assign(state,prev)}render();if(closing){const target=[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===closing.focusAction&&b.dataset.id===closing.focusId)||document.querySelector(`[data-entry="${closing.id}"]`);target?.focus({preventScroll:true})}if(state.feedback){toast(state.feedback);state.feedback=''}});
function toast(message){$('#notice').textContent=message;$('#notice').classList.add('show');clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),3000)}
function stats(r){const absent=['empty','unrated'].includes(state.scenario),unknown=state.scenario==='unavailable';return `<div class="experience"><span class="caption">${t(r==='helper'?'experienceHelper':'experienceOwner')}</span></div><div class="experience">${unknown?icon('cloud-off')+`<span>${t('unavailable')}</span>`:absent?`<span>${t('noReviews')}</span><span class="muted">· ${completedNoun(state.scenario==='empty'?0:3)}</span>`:icon('star')+`<span>${new Intl.NumberFormat(state.locale,{minimumFractionDigits:1,maximumFractionDigits:1}).format(r==='helper'?4.8:4.9)} · ${reviewNoun(r==='helper'?12:7)} · ${completedNoun(r==='helper'?18:10)}</span>`}</div>`}
function appBar(title=null){return `<header class="app-bar">${title?btn('back',icon('arrow-left'),'icon-button','',`aria-label="${t('back')}"`)+`<div class="bar-title">${esc(title)}</div>`:`<span class="brand">petfriendly<span>.</span></span><select class="mode" id="account-mode" aria-label="${t('chooseRole')}"><option value="owner" ${state.mode==='owner'?'selected':''}>${t('owner')}</option><option value="helper" ${state.mode==='helper'?'selected':''}>${t('helper')}</option></select>`}</header>`}
function nav(){const items=state.mode==='helper'?[['discovery','list-filter','requests'],['hub','paw-print','myWalks'],['chats','message-square','chats'],['account','user-round','me']]:[['nearby','compass','nearby'],['people','users-round','people'],['hub','paw-print','walking'],['chats','message-square','chats'],['account','user-round','me']];return `<nav class="bottom-nav" style="--nav-count:${items.length}" aria-label="${state.locale==='ru'?'Основные разделы':'Navigation'}">${items.map(([action,ic,key])=>btn('nav',`<span class="nav-icon">${icon(ic)}</span><span>${t(key)}</span>`,'nav-item',action,state.view===action?'aria-current="page"':'')).join('')}</nav>`}
function status(w){return `<div class="status">${icon({selected:'user-check',searching:'search',active:'footprints',awaiting:'clock',completed:'check',cancelled:'circle-slash'}[w.status])}<span>${t(w.status)}</span></div>`}
function walkFacts(w,compact=false){const zone=w.zone||'Europe/Minsk';return `<div class="facts"><div class="fact">${icon('calendar-days')}<span>${date(w.date,true,zone)} · ${t('duration')}${compact?'':`<br><span class="caption">${t('venueTime')} · ${new Intl.DateTimeFormat(state.locale,{timeZone:zone,timeZoneName:'shortOffset'}).formatToParts(new Date(w.date)).find(p=>p.type==='timeZoneName').value}</span>`}</span></div><div class="fact">${icon('map-pin')}<span>${w.publicDistrict?esc(w.publicDistrict)+' · '+t(w.cityKey||'minsk'):t('district')}</span></div>${compact||!w.person?'':`<div class="fact">${icon('user-round')}<span>${t(w.role==='helper'?'owner':'helper')} · ${esc(w.person)}</span></div>`}</div>`}
function primaryAction(w,detail=false){const label=(key,glyph)=>detail?icon(glyph)+`<span>${t(key)}</span>`:t(key);if(w.status==='searching')return btn('detail',t('candidates'),'secondary',w.id);if(w.status==='selected'&&w.role==='helper')return btn('start',label('start','play'),'primary',w.id);if(w.status==='active'&&w.role==='helper')return btn('finish',label('finish','flag'),'primary',w.id);if(w.status==='awaiting'&&w.role==='owner')return btn('confirm',label('confirm','check'),'primary',w.id);if(w.status==='selected'&&w.role==='owner')return btn('chat',icon('message-square')+`<span>${t('openChat')}</span>`,'primary',w.id);return ''}
function walkCard(w){const chat=w.chat&&!(w.status==='selected'&&w.role==='owner');return `<article class="walk" data-entry="${w.id}" tabindex="-1"><div class="walk-head">${photo('pet',w.missing)}<div><h3>${esc(w.pet)}</h3><span class="caption">${w.person?(w.role==='helper'?t('owner'):t('helper'))+' · '+esc(w.person):role(w.role)}</span></div>${btn('detail',icon('chevron-right'),'icon-button',w.id,`aria-label="${t('details')}: ${esc(w.pet)}"`)}</div>${walkFacts(w,true)}${status(w)}<div class="actions">${primaryAction(w)}${chat?btn('chat',icon('message-square')+t('chat'),'chat-button',w.id):''}</div>${state.actionErrors[w.id]?errorCopy(state.actionErrors[w.id]):''}${w.status==='awaiting'&&w.role==='helper'?`<p class="caption" style="margin-top:8px">${t('waitingCopy')}</p>`:''}</article>`}
function current(){if(state.scenario==='empty')return emptyCurrent();const assigned=state.walks.filter(w=>w.role===state.mode&&!w.discovery&&!w.application&&w.status!=='completed'&&w.status!=='searching').sort((a,b)=>({active:0,awaiting:state.mode==='owner'?0:2,selected:1}[a.status]-{active:0,awaiting:state.mode==='owner'?0:2,selected:1}[b.status])||new Date(a.date)-new Date(b.date));const ownRequests=state.walks.filter(w=>w.role==='owner'&&w.status==='searching');return `<div class="section-head"><h2>${t('assignedGroup')}</h2><span class="caption">${assigned.length}</span></div>${assigned.length?assigned.map(walkCard).join(''):emptyCurrent()}${state.mode==='owner'?`<section class="group"><div class="section-head"><h2>${t('myRequests')}</h2>${btn('new-request',icon('plus')+t('newRequest'),'text-action')}</div>${ownRequests.map(walkCard).join('')}</section>`:state.mode==='helper'?`<details class="group" open><summary>${t('applications')} · ${state.walks.filter(w=>w.application).length}${icon('chevron-down')}</summary>${state.walks.filter(w=>w.application).map(w=>`<article class="application"><h3>${esc(w.pet)}</h3><p class="caption">${date(w.date)} · ${t('district')}</p><div class="status">${icon('send')}<span>${t('applicationSent')}<br>${t('notAssigned')}</span></div>${btn('detail',t('details'),'text-action',w.id)}</article>`).join('')}</details>`:''}`}
function emptyCurrent(){return `<section class="empty">${icon('paw-print')}<h2>${t('emptyCurrent')}</h2><p class="muted">${t(state.mode==='owner'?'emptyOwner':'emptyHelper')}</p>${state.mode==='helper'?btn('discover',t('findRequest'),'primary'):btn('new-request',t('newRequest'),'primary')}</section>`}
words.choose=['Выбрать','Select','Выбраць','Wybierz'];words.editReply=['Изменить ответ','Edit reply','Змяніць адказ','Edytuj odpowiedź'];words.yourReview=['Ваш отзыв','Your review','Ваш водгук','Twoja opinia'];
function historyPage(){if(state.scenario==='empty')return `<section class="empty">${icon('history')}<h2>${t('history')}</h2><p class="muted">${t('emptyHistory')}</p></section>`;const entries=state.history.filter(w=>state.period==='all'||new Date(w.date).getUTCMonth()===(state.period==='oct'?9:8));return `<label class="history-filter"><span>${t('period')}</span><select id="history-period"><option value="all" ${state.period==='all'?'selected':''}>${t('allTime')}</option><option value="oct" ${state.period==='oct'?'selected':''}>${t('october')}</option><option value="sep" ${state.period==='sep'?'selected':''}>${t('september')}</option></select></label><div class="history-list">${entries.slice(0,state.historyLimit).map(w=>`<article class="history-entry" data-entry="${w.id}" tabindex="-1"><details class="history-disclosure" data-history="${w.id}" ${state.expanded['history-'+w.id]?'open':''}><summary>${photo('pet',true)}<span class="history-copy"><strong class="name">${esc(w.pet)}</strong><span class="caption">${date(w.date,false)} · ${role(w.role)}</span><span class="caption">${t(w.role==='owner'?'helper':'owner')} · ${esc(w.person)}</span></span>${icon('chevron-down')}</summary><div class="history-extra">${walkFacts(w,true)}${w.givenReview?`<p class="caption">${t('yourReview')} · ${w.givenReview.rating} / 5</p><p>${esc(w.givenReview.comment)}</p>`:''}</div></details><footer class="history-footer"><span class="history-state">${icon(w.status==='completed'?'check':'circle-slash')}<span>${t(w.status)}</span></span>${w.status==='completed'?w.reviewed?`<span class="review-submitted caption">${icon('check')}${t('reviewSaved')}</span>`:btn('review',icon('star')+t('review'),'history-review',w.id):''}</footer></article>`).join('')}</div>${state.historyLimit<entries.length?`<div class="pagination">${state.historyError?errorCopy(t('moreError')):''}${state.historyLoading?`<p class="caption" role="status">${t('loadingMore')}</p>`:''}${btn('more-history',t(state.historyLoading?'loadingMore':state.historyError?'retry':'moreHistory'),'outline-action','',state.historyLoading?'disabled':'')}</div>`:''}`}

const sampleReview='Александра заранее уточнила привычки собаки и внимательно отнеслась к нашей просьбе идти спокойным маршрутом. Встреча прошла вовремя. После прогулки мы обсудили, как питомец себя чувствовал. Особенно понравилось, что можно было договориться без спешки и лишних сообщений. Будем рады встретиться снова.';
function reviewRows(){return [0,1,2].map(i=>{const key=`${state.profileRole}-${i}`,long=i===1,reply=state.replies[key]??(i===0?'Спасибо! Рада, что прогулка прошла комфортно.':'');return `<article class="review"><div class="review-author">${photo(i%2?'owner':'helper',i===2,true)}<div><strong class="name">${['Ульяна','Екатерина Александровская-Лисовская','Максим'][i]}</strong><p class="caption">${date(`2026-10-0${9-i}T12:00:00Z`,false)}</p></div><span class="review-rating" aria-label="5 / 5">${icon('star')} 5</span></div><p class="review-text">${esc(long&&!state.expanded[key]?sampleReview.slice(0,110)+'…':long?sampleReview:'Спасибо за спокойную прогулку и внимательность к питомцу.')}</p>${long?btn('expand-review',t(state.expanded[key]?'collapse':'readMore')+icon(state.expanded[key]?'chevron-up':'chevron-down'),'inline-disclosure',key,`aria-expanded="${!!state.expanded[key]}"`):''}${reply?`<div class="reply"><strong>${t('replyLabel')}</strong><p>${esc(reply)}</p></div>`:''}${state.expanded['reply-'+key]?`<form class="inline-form" data-form="reply" data-id="${key}"><label><span>${t('replyLabel')}</span><textarea name="reply" data-draft="reply-${key}" maxlength="1000">${esc(state.drafts['reply-'+key]??reply)}</textarea></label>${state.drafts['reply-error-'+key]?errorCopy(t('sendError')):''}<div class="review-controls-row">${btn('reply',t('close'),'text-action',key)}<button class="primary" type="submit">${icon('send')}${t('send')}</button></div></form>`:`<div class="review-controls-row">${btn('reply',icon(reply?'pencil':'message-circle')+t(reply?'editReply':'reply'),'outline-action',key)}</div>`}</article>`}).join('')}

function profilePage(){const r=state.profileRole;return `<label class="role-view"><span>${t('roleView')}</span><select id="reputation-role"><option value="owner" ${r==='owner'?'selected':''}>${t('experienceOwner')}</option><option value="helper" ${r==='helper'?'selected':''}>${t('experienceHelper')}</option></select></label><section class="profile-reputation">${stats(r)}</section>${r==='helper'?`<div class="section-head"><h2>${t('preferences')}</h2></div><dl class="preferences"><div><dt>${t('cityDistrict')}</dt><dd>${esc(state.preferences.city)}</dd></div><div><dt>${t('introduction')}</dt><dd>${esc(state.preferences.bio)}</dd></div><div><dt>${t('sizes')}</dt><dd>${t(state.preferences.sizes==='any'?'anySize':'smallMedium')}</dd></div><div><dt>${t('areas')}</dt><dd>${esc(state.preferences.areas)}</dd></div><div><dt>${t('availability')}</dt><dd>${scheduleSummary(state.preferences)}</dd></div></dl>${btn('edit-preferences',t('editPreferences'),'secondary full')}`:''}<div class="section-head"><h2>${t(r==='helper'?'reviewsHelper':'reviewsOwner')}</h2></div>${['empty','unrated'].includes(state.scenario)?`<section class="empty"><p>${t('noReviews')}</p></section>`:state.scenario==='unavailable'?`<div class="state-message">${icon('cloud-off')}<p>${t('unavailable')}</p></div>${btn('retry',t('retry'),'text-action')}`:reviewRows()}`}
function hub(){const name=state.scenario==='long'?'Александра Владимировна Ковальская-Лисовская':'Александра Ковальская';return `${appBar()}<div class="hub-shell"><header class="hub-heading"><div class="intro"><h1>${t(state.mode==='helper'?'myWalks':'walking')}</h1>${btn('info',icon('info'),'icon-button','',`aria-label="${t('info')}"`)}</div><div class="local-tabs" role="tablist" aria-label="${t('walking')}">${['current','history','profile'].map(k=>btn('tab',t(k),'tab',k,`role="tab" id="tab-${k}" aria-selected="${state.tab===k}" aria-controls="hub-panel" tabindex="${state.tab===k?'0':'-1'}"`)).join('')}</div></header><main class="page hub-content">${state.tab!=='profile'?`<div class="identity compact-identity">${photo('owner',state.scenario==='long',true)}<div><div class="name">${esc(name)}</div><p class="caption">${role(state.mode)}</p></div></div>`:''}<section id="hub-panel" role="tabpanel" aria-labelledby="tab-${state.tab}">${state.tab==='profile'?`<div class="identity profile-identity">${photo('owner',state.scenario==='long')}<div><div class="name">${esc(name)}</div><p class="caption">${role(state.mode)}</p></div></div>`:''}${state.scenario==='loading'?`<div role="status">${t('loading')}<div class="loading"></div><div class="skeleton"></div><div class="skeleton"></div></div>${btn('retry',t('retry'),'text-action')}`:state.scenario==='error'?`${errorCopy(t('error'))}<p class="muted">${t('retryCopy')}</p>${btn('retry',t('retry'),'secondary')}`:state.tab==='current'?current():state.tab==='history'?historyPage():profilePage()}</section><p class="demo-note">${t('demo')}</p></main></div>${nav()}`}
function lookup(id){return state.walks.find(w=>w.id===id)||state.history.find(w=>w.id===id)}
function detailPage(){const w=lookup(state.param);if(!w)return `${appBar(t('agreement'))}<main class="page">${t('unavailableRequest')}</main>`;const candidates=w.status==='searching'&&w.role==='owner';const publicRequest=w.discovery||w.application;return `${appBar(t(publicRequest?'request':'agreement'))}<main class="page"><div class="walk-head">${photo('pet',w.missing)}<div><h1>${esc(w.pet)}</h1><p class="caption">${role(w.role)}</p></div></div>${walkFacts(w)}${status(w)}${state.actionErrors[w.id]?errorCopy(state.actionErrors[w.id]):''}${publicRequest?`<div class="status">${icon('send')}<span>${w.application?t('applicationSent')+' · '+t('notAssigned'):t('request')}</span></div><div class="identity">${photo('owner',false,true)}<div>${esc(w.person)}<p class="caption">${t('experienceOwner')} · 4,9 · ${reviewNoun(7)}</p></div></div>${btn('public',t('publicProfile'),'text-action',w.id)}${btn(w.application?'withdraw':'apply',t(w.application?'withdraw':'apply'),'primary full',w.id)}`:candidates?`<div class="section-head"><h2>${t('chooseCandidate')} · 3</h2></div>${['Ульяна','Мария','Анна'].map((name,i)=>`<article class="candidate candidate-row">${btn('public',photo('helper',i===1,true)+`<span class="candidate-copy"><strong class="name">${name}</strong><span class="caption">${i===1?t('noReviews'):i===0?'4,8 · '+reviewNoun(12):'4,9 · '+reviewNoun(4)}</span></span>`+icon('chevron-right'),'candidate-profile',w.id+'|'+i,`aria-label="${t('publicProfile')}: ${name}"`)}${btn('select-helper',t('choose'),'outline-action',`${w.id}:${i}`,`aria-label="${t('selectHelper')}: ${name}"`)}</article>`).join('')}`:`<div class="actions detail-actions">${primaryAction(w,true)}${w.chat&&!(w.status==='selected'&&w.role==='owner')?btn('chat',icon('message-square')+t('chat'),'chat-button',w.id):''}</div>${w.chat?`<section class="handover-details" aria-labelledby="handover-title"><h2 id="handover-title">${t('privateDetails')}</h2><p class="caption">${t('privateCaption')}</p><p class="handover-copy">Встречаемся у входа со стороны внутреннего двора. Используем привычный поводок; вода в сумке.</p></section>`:''}`}</main>`}
function publicPage(){const [base,candidate]=state.param.split('|'),w=lookup(base),r=w?.role==='helper'?'owner':'helper',candidateName=candidate===undefined?w?.person:['Ульяна','Мария','Анна'][Number(candidate)],newHelper=candidate==='1';return `${appBar(t('publicProfile'))}<main class="page"><div class="identity">${photo(r==='owner'?'owner':'helper')}<div><h1>${esc(candidateName||'Ульяна')}</h1><p class="caption">${t('district')}</p></div></div><h2>${t(r==='owner'?'experienceOwner':'experienceHelper')}</h2><p>${newHelper?t('noReviews'):(r==='helper'?'4,8':'4,9')+' · '+reviewNoun(7)}</p><p>${t('bio')}</p>${newHelper?'':`<article class="review"><strong>Анна</strong><p class="review-rating">${icon('star')} 5</p><p class="review-text">Спасибо за внимательное отношение и спокойное общение.</p></article>`}</main>`}
function chatPage(){const w=lookup(state.param),messages=state.messages[w.id]||[{name:w.person,text:'Здравствуйте! Встречаемся у входа в сквер.',time:'17:42'},{mine:true,text:'Хорошо, буду вовремя. Возьму воду.',time:'17:44'},{name:w.person,image:'walking-assets/pet.jpg',time:'17:45'}];return `${appBar(w.person)}<main class="page chat-page"><div class="chat-context">${t('agreement')} · ${esc(w.pet)}<br>${date(w.date)} · ${t(w.status)}<p class="caption">${t('chatContext')}</p></div><div class="messages">${messages.map(m=>`<article class="bubble ${m.mine?'mine':''}"><strong>${esc(m.mine?'Александра':m.name)}</strong>${m.text?`<p>${esc(m.text)}</p>`:''}${m.image?`<img class="photo-message" src="${m.image}" alt="${t('photo')}">`:''}<time>${m.time}</time></article>`).join('')}</div></main><form class="composer" data-form="chat" data-id="${w.id}">${btn('photo',icon('image'),'icon-button','',`aria-label="${t('selectPhoto')}"`)}<textarea name="message" data-draft="chat-${w.id}" rows="1" placeholder="${t('writeMessage')}" aria-label="${t('writeMessage')}">${esc(state.drafts['chat-'+w.id]||'')}</textarea><button type="submit" class="primary icon-button" aria-label="${t('send')}">${icon('arrow-up')}</button><input type="file" accept="image/*" id="chat-photo" hidden></form>`}
function discoveryPage(){const w=state.walks.find(w=>w.id==='discovery');return `${appBar()}<main class="page"><div class="intro"><h1>${t('requests')}</h1></div><p class="caption">${t('district')}</p>${w?`<article class="walk"><div class="walk-head">${photo('pet')}<h2>${esc(w.pet)}</h2></div>${walkFacts(w)}${btn('detail',t('details'),'primary full',w.id)}</article>`:`<p>${t('unavailableRequest')}</p>`}</main>${nav()}`}
function chatsPage(){return `${appBar()}<main class="page"><h1>${t('chats')}</h1>${state.walks.filter(w=>w.chat).map(w=>`<article class="walk"><h3>${esc(w.person)} · ${esc(w.pet)}</h3><p class="caption">${t(w.status)}</p>${btn('chat',t('openChat'),'text-action',w.id)}</article>`).join('')}</main>${nav()}`}
function otherPage(){return `${appBar()}<main class="page"><h1>${t(state.view==='account'?'me':state.view)}</h1>${state.view==='account'?`<div class="identity">${photo()}<div class="name">Александра Ковальская</div></div>${btn('own-profile',t('returnHub'),'secondary full')}`:`<p class="muted">${t('otherModule')}</p>${btn('hub',t('returnHub'),'secondary')}`}</main>${nav()}`}
function render(){const phone=$('#phone');phone.style.setProperty('--width',state.width+'px');phone.style.setProperty('--scale',state.scale);phone.dataset.theme=state.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):state.theme;phone.lang=state.locale;phone.dataset.large=Number(state.scale)>1.5;$('#app').innerHTML=state.view==='hub'?hub():state.view==='detail'?detailPage():state.view==='public'?publicPage():state.view==='chat'?chatPage():state.view==='discovery'?discoveryPage():state.view==='chats'?chatsPage():otherPage();lucide.createIcons();const p=$('.page');if(p)p.scrollTop=state.scroll[`${state.mode}:${state.view}:${state.tab}`]||0;positionSheet()}
function errorCopy(text){return `<div class="state-message error" role="alert">${icon('circle-alert')}<p>${text}</p></div>`}
words.venueTime=['Время места встречи','Venue-local time','Час месца сустрэчы','Czas miejsca spotkania'];
words.infoRequest=['Запрос и выбор','Request and selection','Запыт і выбар','Prośba i wybór'];words.infoRequestBody=['Владелец выбирает одного помощника из откликов. Отклик ещё не означает назначение.','The owner selects one helper. Applying does not mean being selected.','Уладальнік выбірае аднаго памочніка. Адгук яшчэ не азначае прызначэнне.','Właściciel wybiera jednego pomocnika. Zgłoszenie nie oznacza wyboru.'];
words.infoChat=['Договоритесь в чате','Coordinate in chat','Дамоўцеся ў чаце','Ustalcie szczegóły na czacie'];words.infoChatBody=['После назначения участникам доступен личный чат.','Assigned participants coordinate in a private chat.','Пасля прызначэння ўдзельнікам даступны асабісты чат.','Po wyborze uczestnicy mają dostęp do prywatnego czatu.'];
words.infoFinish=['Прогулка и подтверждение','Walk and confirmation','Прагулка і пацвярджэнне','Spacer i potwierdzenie'];words.infoFinishBody=['Помощник отмечает начало и окончание. Затем владелец подтверждает завершение.','The helper marks the start and finish. Then the owner confirms completion.','Памочнік адзначае пачатак і канец. Потым уладальнік пацвярджае завяршэнне.','Pomocnik oznacza początek i koniec. Następnie właściciel potwierdza zakończenie.'];
words.ratingShort=['Опыт владельца и помощника учитывается отдельно — по опубликованным допустимым отзывам.','Owner and helper reputations are separate, based on published eligible reviews.','Досвед уладальніка і памочніка ўлічваецца асобна — па апублікаваных дапушчальных водгуках.','Reputacje właściciela i pomocnika są oddzielne, oparte na opublikowanych uprawnionych opiniach.'];words.ratingSafety=['Рейтинг помогает выбрать, но не гарантирует безопасность. У мест — отдельный рейтинг.','Ratings support your choice, but do not guarantee safety. Places have separate ratings.','Рэйтынг дапамагае выбраць, але не гарантуе бяспеку. У месцаў — асобны рэйтынг.','Oceny pomagają w wyborze, ale nie gwarantują bezpieczeństwa. Miejsca mają osobne oceny.'];
function positionSheet(){if(!$('#sheet').open)return;const rect=$('#phone').getBoundingClientRect(),bottom=Math.min(innerHeight,rect.bottom-1),visibleHeight=bottom-Math.max(0,rect.top+1);Object.assign($('#sheet').style,{left:(rect.left+1)+'px',bottom:Math.max(0,innerHeight-bottom)+'px',width:(rect.width-2)+'px',maxWidth:(rect.width-2)+'px',maxHeight:Math.max(180,Math.min(visibleHeight-12,rect.height*.88))+'px'})}
function informationBody(){return `<section class="information-process"><h3>${t('helpProcess')}</h3><ol>${['infoRequest','infoChat','infoFinish'].map((k,i)=>`<li><span class="step-number" aria-hidden="true">${i+1}</span><div><h4>${t(k)}</h4><p>${t(k+'Body')}</p></div></li>`).join('')}</ol></section><section class="information-rating"><h3>${t('helpRating')}</h3><p>${t('ratingShort')}</p><p class="caption">${t('ratingSafety')}</p></section><details class="information-rules"><summary>${t('helpReviews')}${icon('chevron-down')}</summary><p>${t('helpReviewsBody')}</p></details>`}
function sheetBody(){const s=state.sheet, w=lookup(s.id),d=state.drafts['review-'+s.id]||{rating:0,comment:''};let title=t(s.kind==='info'?'info':s.kind==='review'?'review':s.kind==='edit'?'editPreferences':'newRequest'),body='';if(s.kind==='info')body=informationBody();if(s.kind==='review')body=`<p class="caption">${t('reviewRecipient')}</p><h3>${esc(w.person)} · ${t(w.role==='owner'?'helper':'owner')}</h3><p class="caption">${esc(w.pet)} · ${date(w.date,false)}</p><form data-form="review" data-id="${w.id}"><fieldset style="border:0;padding:0;margin:16px 0"><legend>${t('rating')}</legend><div class="stars" role="radiogroup" aria-label="${t('rating')}">${[1,2,3,4,5].map(n=>btn('rating',icon('star'),'star',String(n),`aria-label="${n} / 5" role="radio" aria-checked="${n===d.rating}" data-filled="${n<=d.rating}" tabindex="${n===(d.rating||1)?0:-1}"`)).join('')}</div></fieldset><label><span>${t('comment')}</span><textarea name="comment" data-draft="review-comment-${w.id}" maxlength="2000">${esc(d.comment)}</textarea></label>${s.error?errorCopy(s.error):''}<button type="submit" class="primary full" ${state.busy?'disabled':''}>${t(state.busy?'pending':'sendReview')}</button></form>`;if(s.kind==='edit'){const p=state.drafts.preferences||state.preferences;body=`<form data-form="preferences"><label><span>${t('cityDistrict')}</span><input name="city" data-preference="city" value="${esc(p.city)}" required></label><label><span>${t('introduction')}</span><textarea name="bio" data-preference="bio" required>${esc(p.bio)}</textarea></label><label><span>${t('sizes')}</span><select name="sizes" data-preference="sizes"><option value="small" ${p.sizes==='small'?'selected':''}>${t('smallMedium')}</option><option value="any" ${p.sizes==='any'?'selected':''}>${t('anySize')}</option></select></label><label><span>${t('areas')}</span><input name="areas" data-preference="areas" value="${esc(p.areas)}" required></label>${scheduleForm(p)}${s.error?errorCopy(s.error):''}<button type="submit" class="primary full" ${state.busy?'disabled':''}>${t(state.busy?'pending':'save')}</button></form>`}if(s.kind==='request'){const d=state.drafts.request||{},zone=d.city==='warsaw'?'Europe/Warsaw':'Europe/Minsk';body=`<form data-form="request"><label><span>${t('petName')}</span><input name="pet" data-request="pet" value="${esc(d.pet||'Луна')}" required></label><label><span>${t('cityLabel')}</span><select name="city" data-request="city"><option value="minsk" ${d.city!=='warsaw'?'selected':''}>${t('minsk')}</option><option value="warsaw" ${d.city==='warsaw'?'selected':''}>${t('warsaw')}</option></select></label><label><span id="request-date-label">${t('dateLabel')} · ${zone}</span><input type="datetime-local" name="date" data-request="date" value="${esc(d.date||'2026-10-17T18:30')}" required></label><label><span>${t('districtLabel')}</span><input name="district" data-request="district" value="${esc(d.district||'Центральный район')}" required></label><label><span>${t('description')}</span><textarea name="description" data-request="description">${esc(d.description||'')}</textarea></label>${s.error?errorCopy(s.error):''}<button type="submit" class="primary full" ${state.busy?'disabled':''}>${t(state.busy?'pending':'create')}</button></form>`}return `<div class="sheet-inner"><div class="sheet-head"><h2 id="sheet-title">${title}</h2>${btn('close-sheet',icon('x'),'icon-button','',`aria-label="${t('close')}" ${state.busy?'disabled':''}`)}</div><div class="sheet-body ${s.kind==='info'?'information-body':''}">${body}</div></div>`}
function localToUTC(local,zone){const desired=Date.parse(local+':00Z');let guess=desired;for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(guess).map(p=>[p.type,p.value]));guess+=desired-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)}return new Date(guess).toISOString()}
function dayName(day){return new Intl.DateTimeFormat(state.locale,{weekday:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2026,9,11+day)))}
function scheduleSummary(p){const groups=[];for(const d of p.schedule.filter(d=>d.enabled)){const prev=groups.at(-1);if(prev&&prev.last===d.day-1&&prev.start===d.start&&prev.end===d.end)prev.last=d.day;else groups.push({first:d.day,last:d.day,start:d.start,end:d.end})}return groups.map(g=>`${dayName(g.first)}${g.last!==g.first?'–'+dayName(g.last):''} · ${g.start}–${g.end}`).join('<br>')+`<br><span class="caption">${esc(p.zone)}</span>`}
function scheduleForm(p){return `<label><span>${t('timezone')}</span><select name="zone" data-preference="zone"><option ${p.zone==='Europe/Minsk'?'selected':''}>Europe/Minsk</option><option ${p.zone==='Europe/Warsaw'?'selected':''}>Europe/Warsaw</option></select></label><details open><summary>${t('availability')}</summary>${p.schedule.map(d=>`<div class="schedule-row"><label class="day-label"><input type="checkbox" name="day-${d.day}" data-day="${d.day}" data-part="enabled" ${d.enabled?'checked':''}>${dayName(d.day)}</label><div class="time-row"><label><span>${t('from')}</span><input type="time" name="start-${d.day}" value="${d.start}" data-day="${d.day}" data-part="start" aria-label="${dayName(d.day)} ${t('from')}"></label><label><span>${t('until')}</span><input type="time" name="end-${d.day}" value="${d.end}" data-day="${d.day}" data-part="end" aria-label="${dayName(d.day)} ${t('until')}"></label></div></div>`).join('')}</details>`}
function openSheet(kind,id=null){if(state.sheet||state.busy)return;if(kind==='review'){const w=lookup(id);if(!w||w.status!=='completed'||w.reviewed)return}remember();state.sheet={kind,id,error:'',focusAction:document.activeElement?.dataset.action,focusId:document.activeElement?.dataset.id};history.pushState({depth:state.stack.length,sheet:kind},'',location.href);$('#sheet').innerHTML=sheetBody();$('#sheet').showModal();positionSheet();lucide.createIcons();$('#sheet').querySelector('button,input,textarea')?.focus()}
function redrawSheet(){const y=$('#sheet .sheet-body')?.scrollTop||0;$('#sheet').innerHTML=sheetBody();$('#sheet').querySelectorAll('input,textarea,select,.star').forEach(el=>el.disabled=state.busy);lucide.createIcons();$('#sheet .sheet-body').scrollTop=y;positionSheet()}
function closeSheet(){if(!state.busy&&state.sheet)history.back()}
$('#sheet').addEventListener('cancel',e=>{e.preventDefault();closeSheet()});$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet'))closeSheet()});window.addEventListener('resize',positionSheet);
function mutate(action){if(state.busy)return;state.busy=true;action();state.busy=false;render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id,w=lookup(id);if(['close-sheet','rating'].includes(action)){if(action==='close-sheet')closeSheet();else {const key='review-'+state.sheet.id;state.drafts[key]??={rating:0,comment:''};state.drafts[key].rating=Number(id);$('#sheet').querySelectorAll('.star').forEach((el,i)=>{el.setAttribute('aria-checked',i+1===Number(id));el.dataset.filled=i<Number(id);el.tabIndex=i+1===Number(id)?0:-1});}return}if(state.busy)return;if(action==='back')return back();if(action==='tab'){remember();state.tab=id;render();$('#tab-'+id)?.focus();return}if(action==='nav'){if(id==='hub'&&state.view==='hub')return;return navigate(id)}if(action==='hub'){remember();state.view='hub';state.stack=[];history.replaceState({depth:0},'',location.pathname);return render()}if(action==='own-profile'){remember();state.tab='profile';state.profileRole=state.mode;return navigate('hub')}if(action==='discover')return navigate('discovery');if(action==='detail')return navigate('detail',id);if(action==='public')return navigate('public',id);if(action==='chat'&&w?.chat)return navigate('chat',id);if(action==='info')return openSheet('info');if(action==='review')return openSheet('review',id);if(action==='edit-preferences')return openSheet('edit');if(action==='new-request')return openSheet('request');if(action==='more-history')return loadHistory();if(action==='expand-review'||action==='reply'){remember();const key=action==='reply'?'reply-'+id:id;state.expanded[key]=!state.expanded[key];return render()}if(action==='retry'){remember();state.scenario='loading';render();setTimeout(()=>{state.scenario='populated';$('#scenario').value='populated';render()},650);return}if(action==='photo'){return $('#chat-photo').click()}if(action==='select-helper'){const [walkId,n]=id.split(':');return writeAction(action,lookup(walkId),Number(n),id)}if(action==='apply'&&w?.discovery)return writeAction(action,w);if(action==='withdraw'&&w?.application)return writeAction(action,w);if(['start','finish','confirm'].includes(action)&&w)return writeAction(action,w);});
async function loadHistory(){if(state.historyLoading)return;const period=state.period,fail=state.failNext;state.failNext=false;$('#fault').checked=false;remember();state.historyLoading=true;state.historyError=false;render();await new Promise(r=>setTimeout(r,450));state.historyLoading=false;if(period===state.period){state.historyError=fail;if(!fail)state.historyLimit+=6}render()}
async function writeAction(action,w,n=0,pendingId=w?.id){if(!w||state.busy)return;if(action==='select-helper'&&(w.status!=='searching'||w.role!=='owner'))return;const fail=state.failNext;state.failNext=false;$('#fault').checked=false;state.busy=true;state.pendingId=pendingId;remember();render();await new Promise(r=>setTimeout(r,450));state.busy=false;state.pendingId=null;if(fail){state.actionErrors[w.id]=t('actionError');render();return}delete state.actionErrors[w.id];if(action==='select-helper'){w.person=['Ульяна','Мария','Анна'][n];w.status='selected';w.chat=true}if(action==='apply'){w.application=true;w.discovery=false}if(action==='withdraw'){w.application=false;w.discovery=true}if(action==='start'&&w.role==='helper'&&w.status==='selected')w.status='active';if(action==='finish'&&w.role==='helper'&&w.status==='active')w.status='awaiting';if(action==='confirm'&&w.role==='owner'&&w.status==='awaiting'){w.status='completed';state.history.unshift({...w,id:'completed-'+w.id,reviewed:false})}render();toast(action==='apply'?t('applicationSent'):action==='withdraw'?t('withdraw'):t(w.status))}

document.addEventListener('input',e=>{const el=e.target;if(el.dataset.day){state.drafts.preferences??=structuredClone(state.preferences);const row=state.drafts.preferences.schedule.find(d=>d.day===Number(el.dataset.day));row[el.dataset.part]=el.type==='checkbox'?el.checked:el.value;}if(el.dataset.draft){if(el.dataset.draft.startsWith('review-comment-')){const key='review-'+state.sheet.id;state.drafts[key]??={rating:0,comment:''};state.drafts[key].comment=el.value}else state.drafts[el.dataset.draft]=el.value}if(el.dataset.preference){state.drafts.preferences??=structuredClone(state.preferences);state.drafts.preferences[el.dataset.preference]=el.type==='checkbox'?el.checked:el.value}if(el.dataset.request){state.drafts.request??={};state.drafts.request[el.dataset.request]=el.value}});
document.addEventListener('change',e=>{if(e.target.name==='city'&&e.target.dataset.request){state.drafts.request??={};state.drafts.request.city=e.target.value;$('#request-date-label').textContent=t('dateLabel')+' · '+(e.target.value==='warsaw'?'Europe/Warsaw':'Europe/Minsk')}if(e.target.id==='account-mode'){remember();state.mode=e.target.value;state.profileRole=state.mode;render()}if(e.target.id==='history-period'){remember();state.period=e.target.value;state.historyLimit=6;render()}if(e.target.id==='reputation-role'){remember();state.profileRole=e.target.value;render()}if(e.target.id==='chat-photo'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024)return toast(t('photoError'));const w=lookup(state.param);state.messages[w.id]??=[];state.messages[w.id].push({mine:true,image:URL.createObjectURL(file),time:'17:48'});render()}});
document.addEventListener('keydown',e=>{if(e.target.classList.contains('star')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=Number(e.target.dataset.id);const next=e.key==='Home'?1:e.key==='End'?5:Math.min(5,Math.max(1,n+(e.key==='ArrowRight'?1:-1)));const target=$(`#sheet .star[data-id="${next}"]`);target?.click();target?.focus();return}if(e.target.classList.contains('tab')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const keys=['current','history','profile'],index=keys.indexOf(state.tab);remember();state.tab=e.key==='Home'?'current':e.key==='End'?'profile':keys[(index+(e.key==='ArrowRight'?1:2))%3];render();$('#tab-'+state.tab).focus()}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(state.busy)return;const kind=form.dataset.form,id=form.dataset.id;if(kind==='chat'){const text=form.message.value.trim();if(!text)return;state.messages[id]??=[];state.messages[id].push({mine:true,text,time:'17:48'});state.drafts['chat-'+id]='';render();return}if(kind==='review'&&!state.drafts['review-'+id]?.rating){state.sheet.error=t('chooseRating');return redrawSheet()}if(kind==='preferences'&&(!form.city.value.trim()||!form.bio.value.trim()||!form.areas.value.trim())){state.sheet.error=t('fieldRequired');return redrawSheet()}const data=new FormData(form),fail=state.failNext;state.failNext=false;$('#fault').checked=false;state.busy=true;if(state.sheet)redrawSheet();else form.querySelectorAll('button,textarea,input').forEach(el=>el.disabled=true);await new Promise(r=>setTimeout(r,450));state.busy=false;if(fail){if(state.sheet){state.sheet.error=t(kind==='preferences'?'editError':'sendError');redrawSheet()}else {state.drafts['reply-error-'+id]=true;remember();render()}return}if(kind==='review'){lookup(id).givenReview={rating:state.drafts['review-'+id].rating,comment:data.get('comment')};lookup(id).reviewed=true;state.feedback=t('reviewSaved');return closeSheet()}if(kind==='preferences'){state.preferences={...(state.drafts.preferences||state.preferences),city:data.get('city'),bio:data.get('bio'),sizes:data.get('sizes'),areas:data.get('areas'),zone:data.get('zone')};delete state.drafts.preferences;state.feedback=t('saved');return closeSheet()}if(kind==='request'){state.walks.push({id:'created-'+Date.now(),pet:data.get('pet'),person:'',role:'owner',status:'searching',date:localToUTC(data.get('date'),data.get('city')==='warsaw'?'Europe/Warsaw':'Europe/Minsk'),zone:data.get('city')==='warsaw'?'Europe/Warsaw':'Europe/Minsk',publicDistrict:data.get('district'),cityKey:data.get('city'),description:data.get('description'),chat:false});delete state.drafts.request;state.feedback=t('requestSaved');return closeSheet()}if(kind==='reply'){state.replies[id]=data.get('reply');state.expanded['reply-'+id]=false;delete state.drafts['reply-error-'+id];remember();render();toast(t('replySaved'))}});
for(const key of ['theme','locale','width','scale','scenario'])$('#'+key).addEventListener('change',e=>{if(state.sheet)closeSheet();remember();state[key]=e.target.value;$('#notice').classList.remove('show');if(key==='scenario'&&e.target.value==='long')state.historyLimit=12;render()});$('#fault').addEventListener('change',e=>state.failNext=e.target.checked);$('#reset').addEventListener('click',()=>{if(state.sheet)$('#sheet').close();reset()});matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(state.theme==='system')render()});reset();
window.walkingHub={get state(){return state},navigate,render,openSheet};

document.addEventListener('toggle',e=>{if(e.target.matches?.('.history-disclosure')&&e.target.isConnected)state.expanded['history-'+e.target.dataset.history]=e.target.open},true);
